90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	
118	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
119	    /// length encodings and truncated data.
120	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
121	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
122	        if tag & 0x1F == 0x1F {
123	            return Err("multi-byte tags are not supported".to_string());
124	        }
125	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
126	        let (len, header_len) = match first_len {
127	            0x00..=0x7F => (first_len as usize, 2),
128	            0x80 => return Err("indefinite length is not valid DER".to_string()),
129	            0xFF => return Err("reserved length byte".to_string()),
130	            long => {
131	                let n = (long & 0x7F) as usize;
132	                if !(1..=4).contains(&n) {
133	                    return Err("length is too large".to_string());
134	                }
135	                let bytes = buf
136	                    .get(2..2 + n)
137	                    .ok_or_else(|| "truncated long length".to_string())?;
138	                if bytes[0] == 0 {
139	                    return Err("non-minimal length encoding".to_string());
140	                }
141	                let mut len = 0usize;
142	                for &b in bytes {
143	                    len = len
144	                        .checked_shl(8)
145	                        .and_then(|l| l.checked_add(b as usize))
146	                        .ok_or_else(|| "length overflow".to_string())?;
147	                }
148	                if len < 0x80 {
149	                    return Err("non-minimal length encoding".to_string());
150	                }
151	                (len, 2 + n)
152	            }
153	        };
154	        let total = header_len
155	            .checked_add(len)
156	            .filter(|&t| t <= buf.len())
157	            .ok_or_else(|| "truncated TLV content".to_string())?;
158	        Ok((
159	            Tlv {
160	                tag,
161	                content: &buf[header_len..total],
162	            },
163	            &buf[total..],
164	        ))
165	    }
166	
167	    fn read_tagged<'a>(
168	        buf: &'a [u8],
169	        tag: u8,
170	        what: &str,
171	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
172	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
173	        if tlv.tag != tag {
174	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
175	        }
176	        Ok((tlv, rest))
177	    }
178	
179	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
180	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
181	        // signatureValue BIT STRING } — and nothing trailing.
182	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
183	        if !rest.is_empty() {
184	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
185	        }
186	
187	        let c = cert.content;
188	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
189	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
190	        let (sig_value, c) = read_tlv(c)?;
191	        if sig_value.tag != TAG_BIT_STRING {
192	            return Err("signature must be a BIT STRING".to_string());
193	        }
194	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
195	            return Err("invalid signature BIT STRING".to_string());
196	        }
197	        if !c.is_empty() {
198	            return Err("trailing data in Certificate".to_string());
199	        }
200	
201	        // TBSCertificate ::= SEQUENCE {
202	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
203	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
204	        let t = tbs.content;
205	        let (first, t2) = read_tlv(t)?;
206	        let (version, t) = if first.tag == 0xA0 {
207	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
208	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
209	                return Err("invalid certificate version".to_string());
210	            }
211	            (ver.content[0], t2)
212	        } else {
213	            // No explicit version: v1 certificate.
214	            (0u8, t)
215	        };
216	
217	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
218	        let t = t3;
219	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
220	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
221	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
222	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
223	        let (spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
224	        check_spki(spki)?;
225	        // issuerUniqueID [1] and subjectUniqueID [2] are optional context
226	        // fields; they must still each be a complete TLV. The extensions
227	        // field [3] EXPLICIT is decoded in full rather than skipped: see
228	        // `check_extensions`.
229	        let mut extensions_present = false;
230	        while !t.is_empty() {
231	            let tag_hint = t.first().copied();
232	            let (field, rest) = read_tlv(t).map_err(|e| {
233	                // A truncated field whose tag is already readable can still
234	                // be located: tag 0xA3 is the extensions field.
235	                if tag_hint == Some(0xA3) {
236	                    format!("extensions field: {e}")
237	                } else {
238	                    e
239	                }
240	            })?;
241	            if field.tag == 0xA3 {
242	                if extensions_present {
243	                    return Err("duplicate extensions field".to_string());
244	                }
245	                extensions_present = true;
246	                if version != 2 {
247	                    let name = if version == 0 {
248	                        "v1"
249	                    } else {
250	                        "v2"
251	                    };
252	                    return Err(format!(
253	                        "extensions are only allowed in v3 certificates, this is {name}"
254	                    ));
255	                }
256	                check_extensions(field.content)?;
257	            }
258	            t = rest;
259	        }
260	
261	        let serial_hex = format_serial(serial.content)?;
262	        let issuer = format_name(issuer)?;
263	        let subject = format_name(subject)?;
264	
265	        let v = validity.content;
266	        let (nb, v2) = read_tlv(v)?;
267	        let (na, v3) = read_tlv(v2)?;
268	        if !v3.is_empty() {
269	            return Err("trailing data in validity".to_string());
270	        }
271	        let not_before = format_time(nb)?;
272	        let not_after = format_time(na)?;
273	
274	        Ok(Cert {
275	            subject,
276	            issuer,
277	            serial_hex,
278	            not_before,
279	            not_after,
280	        })
281	    }
282	
283	    /// Validate the content of the extensions field, i.e. the bytes wrapped
284	    /// by `[3] EXPLICIT`:
285	    ///
286	    /// ```text
287	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
288	    /// Extension  ::= SEQUENCE {
289	    ///   extnID    OBJECT IDENTIFIER,
290	    ///   critical  BOOLEAN DEFAULT FALSE,
291	    ///   extnValue OCTET STRING }
292	    /// ```
293	    ///
294	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
295	    /// Every extension must contain its OID and OCTET STRING in that order,
296	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
297	    /// Extension contents are never interpreted: unknown but well-formed
298	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
299	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
300	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
301	        if !rest.is_empty() {
302	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
303	        }
304	        if list.content.is_empty() {
305	            return Err("extensions SEQUENCE is empty".to_string());
306	        }
307	
308	        let mut buf = list.content;
309	        while !buf.is_empty() {
310	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
311	            buf = rest;
312	
313	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
314	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
315	
316	            // critical is optional; whatever stands between the OID and the
317	            // OCTET STRING must be exactly one BOOLEAN if it is present.
318	            let (maybe_bool, after_critical) = read_tlv(after_oid)
319	                .map_err(|e| format!("extension after OID: {e}"))?;
320	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
321	                match maybe_bool.content {
322	                    [0xFF] => {}
323	                    [0x00] => {
324	                        return Err(
325	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
326	                                .to_string()
327	                        )
328	                    }
329	                    _ => {
330	                        return Err(
331	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
332	                        )
333	                    }
334	                }
335	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
336	            } else {
337	                // Not a BOOLEAN: this element must itself be the extnValue.
338	                if maybe_bool.tag != TAG_OCTET_STRING {
339	                    return Err(format!(
340	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
341	                         got tag 0x{:02X}",
342	                        maybe_bool.tag
343	                    ));
344	                }
345	                (maybe_bool, after_critical)
346	            };
347	            // An empty OCTET STRING is legal; its bytes are not interpreted.
348	            let _ = octets.content;
349	            if !after_octets.is_empty() {
350	                return Err("trailing data in extension".to_string());
351	            }
352	        }
353	        Ok(())
354	    }
355	
356	    /// SubjectPublicKeyInfo ::= SEQUENCE {
357	    ///   algorithm        AlgorithmIdentifier,
358	    ///   subjectPublicKey BIT STRING }
359	    /// Nothing may be missing and no extra elements may follow.
360	    fn check_spki(spki: Tlv) -> Result<(), String> {
361	        let (alg, rest) = read_tagged(
362	            spki.content,
363	            TAG_SEQUENCE,
364	            "subjectPublicKeyInfo algorithm identifier",
365	        )?;
366	        check_algorithm_identifier(alg)?;
367	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
368	        check_bit_string(key.content, "subjectPublicKey")?;
369	        if !rest.is_empty() {
370	            return Err("trailing data in subjectPublicKeyInfo".to_string());
371	        }
372	        Ok(())
373	    }
374	
375	    /// AlgorithmIdentifier ::= SEQUENCE {
376	    ///   algorithm  OBJECT IDENTIFIER,
377	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
378	    /// The parameters, if present, must be exactly one complete DER TLV;
379	    /// absent parameters and an explicit NULL are both accepted. The
380	    /// parameter content is not interpreted for any particular algorithm.
381	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
382	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
383	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
384	        if rest.is_empty() {
385	            return Ok(());
386	        }
387	        let (_params, after) =
388	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
389	        if !after.is_empty() {
390	            return Err("multiple algorithm parameters".to_string());
391	        }
392	        Ok(())
393	    }
394	
395	    /// Validate the DER content of a BIT STRING: one leading byte counting
396	    /// unused bits (0..=7), and when the count is nonzero those low bits of
397	    /// the final data byte must all be zero. An empty bit string is only
398	    /// legal with a zero count.
399	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
400	        let unused = *content
401	            .first()
402	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
403	        if unused > 7 {
404	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
405	        }
406	        let data = &content[1..];
407	        if data.is_empty() {
408	            if unused != 0 {
409	                return Err(format!(
410	                    "{what} BIT STRING declares {unused} unused bits but has no data"
411	                ));
412	            }
413	            return Ok(());
414	        }
415	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
416	            return Err(format!(
417	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
418	            ));
419	        }
420	        Ok(())
421	    }
422	
423	    /// Render the serial number as upper-case hex, matching the integer value
424	    /// (a DER sign-padding 0x00 byte is not part of the number).
425	    fn format_serial(content: &[u8]) -> Result<String, String> {
426	        if content.is_empty() {
427	            return Err("empty serial number".to_string());
428	        }
429	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
430	            return Err("non-minimal serial number encoding".to_string());
431	        }
432	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
433	            return Err("non-minimal serial number encoding".to_string());
434	        }
435	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
436	            return Err("negative serial number".to_string());
437	        }
438	        let digits = if content.len() > 1 && content[0] == 0x00 {
439	            &content[1..]
440	        } else {
441	            content
442	        };
443	        let mut s = String::with_capacity(digits.len() * 2);
444	        for b in digits {
445	            write!(s, "{b:02X}").unwrap();
446	        }
447	        if s.is_empty() {
448	            s.push_str("00");
449	        }
450	        Ok(s)
451	    }
452	
453	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
454	    /// multi-valued RDNs joined with '+'). Values of known attribute types
455	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
456	    /// when their tag has a text decoder; a known type carrying any other
457	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
458	    /// name and uses the '#' form carrying the value's full DER encoding in
459	    /// hex. Attributes without a known short name use their dotted OID with
460	    /// the same '#' form.
461	    fn format_name(name: Tlv) -> Result<String, String> {
462	        let mut rdn_buf = name.content;
463	        let mut rdns: Vec<String> = Vec::new();
464	        while !rdn_buf.is_empty() {
465	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
466	            rdn_buf = rest;
467	
468	            let mut atv_buf = set.content;
469	            let mut parts = Vec::new();
470	            while !atv_buf.is_empty() {
471	                let (atv, rest) =
472	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
473	                atv_buf = rest;
474	
475	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
476	                let (value, after_value) = read_tlv(after_oid)?;
477	                if !after_value.is_empty() {
478	                    return Err("trailing data in attribute value".to_string());
479	                }
480	
481	                let oid_arcs = parse_oid(oid.content)?;
482	                match oid_short_name(&oid_arcs) {
483	                    Some(label) => {
484	                        if is_text_value_tag(value.tag) {
485	                            // Supported string type: decode to escaped text.
486	                            // A decode failure (e.g. invalid UTF-8) means the
487	                            // certificate is corrupt; it must not be salvaged
488	                            // by falling back to the hex form.
489	                            let text = decode_attribute_value(value.tag, value.content)?;
490	                            parts.push(format!("{label}={}", escape_value(&text)));
491	                        } else {
492	                            // Known type but a legal value with no text decoder
493	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
494	                            // and show the full original DER encoding as '#'-hex.
495	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
496	                        }
497	                    }
498	                    None => {
499	                        // Unknown attribute type: RFC 4514 requires the form
500	                        // OID=#hex, where the hex is the full DER encoding
501	                        // (tag, length and content) of the attribute value.
502	                        // The value is still validated: a UTF8String must
503	                        // hold valid UTF-8 even when shown as hex.
504	                        if value.tag == 0x0C {
505	                            std::str::from_utf8(value.content)
506	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
507	                        }
508	                        let hex = value_hex(after_oid, after_value);
509	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
510	                    }
511	                }
512	            }
513	            if parts.is_empty() {
514	                return Err("empty RelativeDistinguishedName".to_string());
515	            }
516	            rdns.push(parts.join("+"));
517	        }
518	        rdns.reverse();
519	        Ok(rdns.join(","))
520	    }
521	
522	    /// Uppercase hex of one complete value TLV, sliced straight from the
523	    /// input bytes (`around` ends at `rest`). The original tag and length
524	    /// bytes survive verbatim, including a legal long-form length; nothing is
525	    /// re-encoded and content alone is never emitted.
526	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
527	        let tlv_len = around.len() - rest.len();
528	        let mut hex = String::with_capacity(tlv_len * 2);
529	        for b in &around[..tlv_len] {
530	            write!(hex, "{b:02X}").unwrap();
531	        }
532	        hex
533	    }
534	
535	    /// Tags whose attribute values have a direct text decoding in
536	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
537	    /// legal non-text value for display purposes and is rendered as '#'-hex.
538	    fn is_text_value_tag(tag: u8) -> bool {
539	        matches!(
540	            tag,
541	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
542	        )
543	    }
544	
545	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
546	        if content.is_empty() {
547	            return Err("empty OID".to_string());
548	        }
549	        let mut arcs = Vec::new();
550	        // The first subidentifier encodes the first two arcs as
551	        // 40*first + second and is itself a base-128 quantity, so it can
552	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
553	        let mut i = 0;
554	        let first = read_oid_arc(content, &mut i)?;
555	        match first {
556	            0..=39 => {
557	                arcs.push(0);
558	                arcs.push(first);
559	            }
560	            40..=79 => {
561	                arcs.push(1);
562	                arcs.push(first - 40);
563	            }
564	            _ => {
565	                arcs.push(2);
566	                arcs.push(first - 80);
567	            }
568	        }
569	        while i < content.len() {
570	            arcs.push(read_oid_arc(content, &mut i)?);
571	        }
572	        Ok(arcs)
573	    }
574	
575	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
576	    /// continuation bytes and non-minimal encodings.
577	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
578	        let start = *i;
579	        let mut value = 0u64;
580	        loop {
581	            let b = *content
582	                .get(*i)
583	                .ok_or_else(|| "truncated OID arc".to_string())?;
584	            value = value
585	                .checked_mul(128)
586	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
587	                .ok_or_else(|| "OID arc overflow".to_string())?;
588	            *i += 1;
589	            if b & 0x80 == 0 {
590	                break;
591	            }
592	        }
593	        if *i - start > 1 && content[start] == 0x80 {
594	            return Err("non-minimal OID arc encoding".to_string());
595	        }
596	        Ok(value)
597	    }
598	
599	    fn arcs_to_string(arcs: &[u64]) -> String {
600	        arcs.iter()
601	            .map(u64::to_string)
602	            .collect::<Vec<_>>()
603	            .join(".")
604	    }
605	
606	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
607	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
608	        let name = match arcs {
609	            [2, 5, 4, 3] => "CN",
610	            [2, 5, 4, 4] => "SN",
611	            [2, 5, 4, 5] => "serialNumber",
612	            [2, 5, 4, 6] => "C",
613	            [2, 5, 4, 7] => "L",
614	            [2, 5, 4, 8] => "ST",
615	            [2, 5, 4, 9] => "STREET",
616	            [2, 5, 4, 10] => "O",
617	            [2, 5, 4, 11] => "OU",
618	            [2, 5, 4, 12] => "title",
619	            [2, 5, 4, 17] => "postalAddress",
620	            [2, 5, 4, 18] => "postalCode",
621	            [2, 5, 4, 20] => "telephoneNumber",
622	            [2, 5, 4, 42] => "givenName",
623	            [2, 5, 4, 43] => "initials",
624	            [2, 5, 4, 44] => "generationQualifier",
625	            [2, 5, 4, 46] => "dnQualifier",
626	            [2, 5, 4, 65] => "pseudonym",
627	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
628	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
629	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
630	            _ => return None,
631	        };
632	        Some(name)
633	    }
634	
635	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
636	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
637	        let s = match tag {
638	            0x0C => std::str::from_utf8(content)
639	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
640	                .to_string(),
641	            // ASCII-family strings: every byte is also its Unicode code point.
642	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
643	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
644	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
645	            0x1E => {
646	                if content.len() % 2 != 0 {
647	                    return Err("odd-length BMPString".to_string());
648	                }
649	                let units: Vec<u16> = content
650	                    .chunks_exact(2)
651	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
652	                    .collect();
653	                char::decode_utf16(units.iter().copied())
654	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
655	                    .collect::<Result<String, _>>()?
656	            }
657	            0x1C => {
658	                if content.len() % 4 != 0 {
659	                    return Err("invalid UniversalString length".to_string());
660	                }
661	                let mut s = String::new();
662	                for c in content.chunks_exact(4) {
663	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
664	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
665	                        return Err("invalid code point in UniversalString".to_string());
666	                    }
667	                    s.push(char::from_u32(cp).unwrap());
668	                }
669	                s
670	            }
671	            _ => {
672	                return Err(format!(
673	                    "unsupported attribute value string type (tag 0x{tag:02X})"
674	                ))
675	            }
676	        };
677	        Ok(s)
678	    }
679	
680	    /// RFC 4514 value escaping; everything above the ASCII control range
681	    /// (including CJK text) passes through unchanged.
682	    fn escape_value(value: &str) -> String {
683	        let mut out = String::with_capacity(value.len());
684	        let last = value.chars().count().saturating_sub(1);
685	        for (i, c) in value.chars().enumerate() {
686	            let at_edge = i == 0 || i == last;
687	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
688	                || (at_edge && (c == ' ' || c == '#'));
689	            if needs_backslash {
690	                out.push('\\');
691	                out.push(c);
692	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
693	                let mut buf = [0u8; 4];
694	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
695	                write!(out, "\\{b:02X}").unwrap();
696	            } else {
697	                out.push(c);
698	            }
699	        }
700	        out
701	    }
702	
703	    fn format_time(tlv: Tlv) -> Result<String, String> {
704	        let (y, mo, d, h, mi, se) = match tlv.tag {
705	            TAG_UTC_TIME => {
706	                let c = tlv.content;
707	                if c.len() != 13 || c[12] != b'Z' {
708	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
709	                }
710	                let digits = &c[..12];
711	                if !digits.iter().all(|b| b.is_ascii_digit()) {
712	                    return Err("non-numeric UTCTime".to_string());
713	                }
714	                let n = |a: usize, b: usize| -> u32 {
715	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
716	                };
717	                let yy = n(0, 1);
718	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
719	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
720	            }
721	            TAG_GENERALIZED_TIME => {
722	                let c = tlv.content;
723	                if c.len() != 15 || c[14] != b'Z' {
724	                    return Err(
725	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
726	                    );
727	                }
728	                let digits = &c[..14];
729	                if !digits.iter().all(|b| b.is_ascii_digit()) {
730	                    return Err("non-numeric GeneralizedTime".to_string());
731	                }
732	                let n = |a: usize, b: usize| -> u32 {
733	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
734	                };
735	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
736	            }
737	            other => return Err(format!("invalid time tag 0x{other:02X}")),
738	        };
739	        validate_datetime(y, mo, d, h, mi, se)?;
740	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
741	    }
742	
743	    fn validate_datetime(
744	        year: i32,
745	        month: u32,
746	        day: u32,
747	        hour: u32,
748	        minute: u32,
749	        second: u32,
750	    ) -> Result<(), String> {
751	        if !(1..=12).contains(&month) {
752	            return Err("invalid month in certificate time".to_string());
753	        }
754	        if hour > 23 || minute > 59 || second > 59 {
755	            return Err("invalid time of day in certificate time".to_string());
756	        }
757	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
758	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
759	        if day < 1 || day > days[(month - 1) as usize] {
760	            return Err("invalid day in certificate time".to_string());
761	        }
762	        Ok(())
763	    }
764	}
