1	//! End-to-end regression tests for X.509 extensions decoding when running
2	//! `chainview inspect <DER-FILE>`.
3	//!
4	//! The extensions field never appears among the five displayed fields, but it
5	//! must be read in full: inspect used to skip the interior of the `[3]`
6	//! wrapper as long as its outer length was intact, so a corrupted extension
7	//! still printed the certificate. These tests pin the fixed contract:
8	//!
9	//! - the field is OPTIONAL and, when present, legal only in an explicit v3
10	//!   certificate (v1 without a version, explicit v1 and v2 must reject it);
11	//! - it may occur at most once; the `[3] EXPLICIT` wrapper contains exactly
12	//!   one non-empty SEQUENCE of extensions;
13	//! - every Extension is a SEQUENCE of OID, optional BOOLEAN, OCTET STRING in
14	//!   that order with nothing appended; the OID must be complete and encoded in
15	//!   minimal form;
16	//! - `critical` omitted means FALSE; an explicit BOOLEAN is accepted only as
17	//!   the DER encoding of TRUE (content exactly FF). Explicit FALSE, other
18	//!   nonzero bytes, empty content and multi-byte contents are all rejected;
19	//! - unknown but legal extension OIDs, critical TRUE and empty OCTET STRING
20	//!   values are all accepted; extension bytes are never interpreted.
21	//!
22	//! Every case drives the real binary: success prints exactly the five fixed
23	//! fields (no extension summary is added); failure is exit code 2, completely
24	//! empty stdout and a `chainview: invalid DER certificate: <reason>` stderr
25	//! whose reason locates the problem in the extensions field.
26	
27	use std::fs;
28	use std::path::PathBuf;
29	use std::process::{Command, Output};
30	use std::sync::atomic::{AtomicU64, Ordering};
31	
32	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
33	const FIXED_SUBJECT: &str = "CN=example.com";
34	const FIXED_ISSUER: &str = "CN=Test CA";
35	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
36	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
37	
38	// An unremarkable private extension OID the tool does not recognize.
39	const UNKNOWN_OID: &[u64] = &[1, 2, 3, 4];
40	
41	// ----- Success: legal encodings ---------------------------------------------
42	
43	#[test]
44	fn v3_certificate_without_extensions_is_accepted() {
45	    // Explicit v3 with no [3] field is perfectly legal.
46	    let cert = build_cert(Some(2), &[]);
47	    assert_success(&run_inspect("v3-no-ext", &cert));
48	}
49	
50	#[test]
51	fn v3_certificate_with_one_unknown_extension_is_accepted() {
52	    // Unknown extension types need no allow-list match: a complete,
53	    // minimal-form OID with any OCTET STRING body is accepted.
54	    let ext = extension(UNKNOWN_OID, None, &[0x30, 0x00]);
55	    let cert = build_cert(Some(2), &extensions_field(&ext));
56	    assert_success(&run_inspect("v3-one-ext", &cert));
57	}
58	
59	#[test]
60	fn v3_certificate_with_critical_extension_is_accepted() {
61	    // critical TRUE (01 01 FF) never causes inspect to fail.
62	    let ext = extension(UNKNOWN_OID, Some(true), b"data");
63	    let cert = build_cert(Some(2), &extensions_field(&ext));
64	    assert_success(&run_inspect("v3-critical", &cert));
65	}
66	
67	#[test]
68	fn v3_certificate_with_empty_extension_octet_string_is_accepted() {
69	    // The extnValue OCTET STRING may carry zero bytes; nothing inside it is
70	    // interpreted.
71	    let ext = extension(UNKNOWN_OID, None, &[]);
72	    let cert = build_cert(Some(2), &extensions_field(&ext));
73	    assert_success(&run_inspect("v3-empty-octets", &cert));
74	}
75	
76	#[test]
77	fn v3_certificate_with_multiple_extensions_is_accepted() {
78	    // A non-empty SEQUENCE may hold many extensions, mixing critical and
79	    // non-critical and using multi-byte OID arcs.
80	    let a = extension(&[1, 2, 840, 99999, 7], Some(true), &[0x01]);
81	    let b = extension(&[2, 5, 29, 14], None, &[0x04, 0x02, 0xAA, 0xBB]);
82	    let c = extension(UNKNOWN_OID, None, &[]);
83	    let cert = build_cert(Some(2), &extensions_field(&concat(&[&a, &b, &c])));
84	    assert_success(&run_inspect("v3-multi-ext", &cert));
85	}
86	
87	#[test]
88	fn v3_extensions_coexist_with_unique_id_fields() {
89	    // issuerUniqueID [1] / subjectUniqueID [2] sit in the same optional tail;
90	    // they must not be mistaken for the [3] extensions field.
91	    let issuer_uid = raw_tlv(0x81, &[0x03], &[0x00, 0xFF, 0xFF]);
92	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
93	    let tail = concat(&[&issuer_uid, &extensions_field(&ext)]);
94	    let cert = build_cert(Some(2), &tail);
95	    assert_success(&run_inspect("v3-unique-id", &cert));
96	}
97	
98	#[test]
99	fn expired_or_future_certificate_with_extensions_is_still_displayed() {
100	    // Validity is not judged: extensions decode the same on an already
101	    // expired and a not-yet-valid certificate. The two certs intentionally
102	    // differ from the fixed validity dates, so their times are checked
103	    // directly rather than via assert_success.
104	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
105	    let field = extensions_field(&ext);
106	
107	    let expired = build_cert_times(Some(2), &field, b"200115093000Z", b"210115093000Z");
108	    assert_ok_fields(
109	        &run_inspect("ext-expired", &expired),
110	        "2020-01-15T09:30:00Z",
111	        "2021-01-15T09:30:00Z",
112	    );
113	
114	    let future = build_cert_times(Some(2), &field, b"280115093000Z", b"290115093000Z");
115	    assert_ok_fields(
116	        &run_inspect("ext-future", &future),
117	        "2028-01-15T09:30:00Z",
118	        "2029-01-15T09:30:00Z",
119	    );
120	}
121	
122	// ----- Failure: version rules -----------------------------------------------
123	
124	#[test]
125	fn v1_certificate_without_version_carrying_extensions_is_rejected() {
126	    // No [0] version field means v1; v1 cannot carry extensions.
127	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
128	    let cert = build_cert(None, &extensions_field(&ext));
129	    assert_invalid_certificate(&run_inspect("v1-ext", &cert));
130	}
131	
132	#[test]
133	fn explicit_v1_certificate_carrying_extensions_is_rejected() {
134	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
135	    let cert = build_cert(Some(0), &extensions_field(&ext));
136	    assert_invalid_certificate(&run_inspect("v1explicit-ext", &cert));
137	}
138	
139	#[test]
140	fn explicit_v2_certificate_carrying_extensions_is_rejected() {
141	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
142	    let cert = build_cert(Some(1), &extensions_field(&ext));
143	    assert_invalid_certificate(&run_inspect("v2-ext", &cert));
144	}
145	
146	#[test]
147	fn duplicate_extensions_field_is_rejected() {
148	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
149	    let field = extensions_field(&ext);
150	    let cert = build_cert(Some(2), &concat(&[&field, &field]));
151	    assert_invalid_certificate(&run_inspect("dup-ext", &cert));
152	}
153	
154	// ----- Failure: [3] wrapper contents ----------------------------------------
155	
156	#[test]
157	fn empty_extensions_wrapper_is_rejected() {
158	    // [3] EXPLICIT with no content at all.
159	    let cert = build_cert(Some(2), &tlv(0xA3, &[]));
160	    assert_invalid_certificate(&run_inspect("wrap-empty", &cert));
161	}
162	
163	#[test]
164	fn extensions_wrapper_without_sequence_is_rejected() {
165	    // The single wrapped element must be a SEQUENCE, even if some other
166	    // complete TLV is present.
167	    let cert = build_cert(Some(2), &tlv(0xA3, &tlv(0x02, &[0x01, 0x00])));
168	    assert_invalid_certificate(&run_inspect("wrap-no-seq", &cert));
169	}
170	
171	#[test]
172	fn extensions_wrapper_with_two_sequences_is_rejected() {
173	    // Exactly one Extensions SEQUENCE belongs inside the wrapper.
174	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
175	    let list = tlv(0x30, &ext);
176	    let cert = build_cert(Some(2), &tlv(0xA3, &concat(&[&list, &list])));
177	    assert_invalid_certificate(&run_inspect("wrap-two-seq", &cert));
178	}
179	
180	#[test]
181	fn extensions_wrapper_with_trailing_element_is_rejected() {
182	    let ext = extension(UNKNOWN_OID, None, &[0x00]);
183	    let inner = concat(&[&tlv(0x30, &ext), &tlv(0x02, &[0x01, 0x2A])]);
184	    let cert = build_cert(Some(2), &tlv(0xA3, &inner));
185	    assert_invalid_certificate(&run_inspect("wrap-trailing", &cert));
186	}
187	
188	#[test]
189	fn empty_extensions_sequence_is_rejected() {
190	    // Extensions ::= SEQUENCE SIZE (1..MAX): zero extensions is invalid.
191	    let cert = build_cert(Some(2), &tlv(0xA3, &tlv(0x30, &[])));
192	    assert_invalid_certificate(&run_inspect("ext-seq-empty", &cert));
193	}
194	
195	#[test]
196	fn truncated_extensions_wrapper_is_rejected() {
197	    // The wrapper announces 8 content bytes but the TBS certificate provides
198	    // only 4; a correct outer length must not hide a truncated interior.
199	    let wrapper = raw_tlv(0xA3, &[0x08], &[0x30, 0x06, 0x06, 0x01]);
200	    let cert = build_cert(Some(2), &wrapper);
201	    assert_invalid_certificate(&run_inspect("wrap-truncated", &cert));
202	}
203	
204	// ----- Failure: individual extension items ----------------------------------
