338	fn extension_critical_with_nonzero_nonff_byte_is_rejected() {
339	    // 0x01 and 0x7F are truthy BER BOOLEANs but not the DER value of TRUE.
340	    for (i, byte) in [0x01u8, 0x7F, 0xFE].into_iter().enumerate() {
341	        let body = tlv(
342	            0x30,
343	            &concat(&[
344	                &oid(UNKNOWN_OID),
345	                &tlv(0x01, &[byte]),
346	                &tlv(0x04, &[0x00]),
