398	    // 0x88 promises another base-128 byte that never arrives; the wrapper
399	    // lengths around it are all correct.
400	    let body = tlv(
401	        0x30,
402	        &concat(&[&tlv(0x06, &[0x88]), &tlv(0x04, &[0x00])]),
403	    );
