409	fn extension_with_nonminimal_oid_is_rejected() {
410	    // Arc 1 as 0x80 0x01 is not the shortest base-128 encoding.
411	    let body = tlv(
412	        0x30,
413	        &concat(&[&tlv(0x06, &[0x80, 0x01]), &tlv(0x04, &[0x00])]),
414	    );
415	    let cert = build_cert(Some(2), &tlv(0xA3, &tlv(0x30, &body)));
416	    assert_invalid_certificate(&run_inspect("ext-oid-nonmin", &cert));
