//! Scratch verification for the unique-ID tail rules. Deleted after the run.
use std::fs;
use std::path::PathBuf;
use std::process::Command;
use std::sync::atomic::{AtomicU64, Ordering};

const UNKNOWN_OID: &[u64] = &[1, 2, 3, 4];

fn accept(tag: &str, tail: &[u8], version: Option<u8>) {
    let cert = build_cert(version, tail);
    let out = run_inspect(tag, &cert);
    assert_eq!(out.status.code(), Some(0), "want accept, stderr={}", lossy(&out.stderr));
    assert!(out.stderr.is_empty());
    assert!(!out.stdout.is_empty());
}

fn reject(tag: &str, tail: &[u8], version: Option<u8>, needle: &str) {
    let cert = build_cert(version, tail);
    let out = run_inspect(tag, &cert);
    assert_eq!(out.status.code(), Some(2), "want reject ({needle}), stdout={}", lossy(&out.stdout));
    assert!(out.stdout.is_empty(), "stdout must be empty: {}", lossy(&out.stdout));
    let err = lossy(&out.stderr);
    assert!(err.starts_with("chainview: invalid DER certificate: "), "stderr: {err}");
    assert!(
        err.to_ascii_lowercase().contains(needle),
        "reason should mention {needle:?}: {err}"
    );
}

fn uid(tag: u8, bs_content: &[u8]) -> Vec<u8> {
    tlv(tag, bs_content)
}

fn ext_field() -> Vec<u8> {
    let mut content = oid(UNKNOWN_OID);
    content.extend_from_slice(&tlv(0x04, &[0x00]));
    let ext = tlv(0x30, &content);
    tlv(0xA3, &tlv(0x30, &ext))
}

#[test]
fn unique_id_rules() {
    let issuer = uid(0x81, &[0x00, 0xFF, 0xFF]);
    let subject = uid(0x82, &[0x03, 0xF8]);

    // --- accepts ---
    accept("v2-issuer-only", &issuer, Some(1));
    accept("v2-subject-only", &subject, Some(1));
    accept("v3-subject-only", &subject, Some(2));
    accept("v2-both", &concat(&[&issuer, &subject]), Some(1));
    accept("v2-both-same-value", &concat(&[
        &uid(0x81, &[0x00, 0x00, 0xAB]),
        &uid(0x82, &[0x00, 0x00, 0xAB]),
    ]), Some(1));
    accept("v3-issuer-ext", &concat(&[&issuer, &ext_field()]), Some(2));
    accept("v3-subject-ext", &concat(&[&subject, &ext_field()]), Some(2));
    accept("v3-both-ext", &concat(&[&issuer, &subject, &ext_field()]), Some(2));
    // count byte 0 with no data
    accept("uid-empty-zero", &uid(0x81, &[0x00]), Some(1));
    // only zero data bytes, count 7
    accept("uid-zero-byte-data", &uid(0x82, &[0x07, 0x00, 0x00]), Some(1));
    // no unique ids at all
    accept("v2-no-tail", &[], Some(1));
    accept("v1-no-tail", &[], None);
    accept("v3-ext-only", &ext_field(), Some(2));

    // --- version rules ---
    reject("v1none-issuer", &issuer, None, "issueruniqueid");
    reject("v1none-subject", &subject, None, "subjectuniqueid");
    reject("v1explicit-issuer", &issuer, Some(0), "issueruniqueid");
    reject("v1explicit-subject", &subject, Some(0), "subjectuniqueid");

    // --- order / cardinality ---
    reject("order-reversed", &concat(&[&subject, &issuer]), Some(1), "issueruniqueid");
    reject("dup-issuer", &concat(&[&issuer, &issuer]), Some(1), "duplicate issueruniqueid");
    reject("dup-subject", &concat(&[
        &issuer, &subject, &subject
    ]), Some(1), "duplicate subjectuniqueid");
    reject("issuer-after-ext", &concat(&[&ext_field(), &issuer]), Some(2), "issueruniqueid");
    reject("subject-after-ext", &concat(&[
        &issuer, &ext_field(), &subject
    ]), Some(2), "subjectuniqueid");
    reject("two-ext", &concat(&[
        &issuer, &ext_field(), &ext_field()
    ]), Some(2), "duplicate extensions");

    // --- explicit / constructed tagging rejected ---
    reject("explicit-a1", &tlv(0xA1, &tlv(0x03, &[0x00])), Some(1), "issueruniqueid");
    reject("explicit-a2", &tlv(0xA2, &tlv(0x03, &[0x00])), Some(1), "subjectuniqueid");

    // --- BIT STRING content rules ---
    reject("uid-missing-count", &uid(0x81, &[]), Some(1), "issueruniqueid");
    reject("uid-count-8", &uid(0x81, &[0x08]), Some(1), "issueruniqueid");
    reject("uid-count-nonzero-nodata", &uid(0x82, &[0x01]), Some(1), "subjectuniqueid");
    reject("uid-tail-bits-set", &uid(0x81, &[0x01, 0x03]), Some(1), "issueruniqueid");
    reject("uid-tail-bits-set-7", &uid(0x82, &[0x07, 0x01]), Some(1), "subjectuniqueid");

    // --- unknown fields in the tail ---
    reject("unknown-tag", &tlv(0x84, &[0x00]), Some(2), "subjectpublickeyinfo");
    reject("unknown-after-ext", &concat(&[
        &ext_field(), &tlv(0x02, &[0x01, 0x01])
    ]), Some(2), "subjectpublickeyinfo");
    reject("unknown-between-uids", &concat(&[
        &issuer, &tlv(0x04, &[0x00]), &subject
    ]), Some(1), "subjectpublickeyinfo");

    // --- truncated UID outer length still located ---
    let broken = raw_tlv(0x81, &[0x05], &[0x00]);
    reject("uid-truncated", &broken, Some(1), "issueruniqueid");
}

fn lossy(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

fn run_inspect(tag: &str, data: &[u8]) -> std::process::Output {
    let cert = TempCert::new(tag, data);
    Command::new(env!("CARGO_BIN_EXE_chainview"))
        .arg("inspect")
        .arg(&cert.path)
        .output()
        .expect("running chainview")
}

struct TempCert {
    path: PathBuf,
}

impl TempCert {
    fn new(tag: &str, data: &[u8]) -> Self {
        static COUNTER: AtomicU64 = AtomicU64::new(0);
        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "chainview-uid-scratch-{}-{tag}-{unique}.der",
            std::process::id()
        ));
        fs::write(&path, data).expect("writing temp certificate");
        TempCert { path }
    }
}

impl Drop for TempCert {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

fn build_cert(version: Option<u8>, tail: &[u8]) -> Vec<u8> {
    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
    let validity = seq(&concat(&[
        &tlv(0x17, b"260115093000Z"),
        &tlv(0x17, b"270115093000Z"),
    ]));
    let subject = simple_cn_name("example.com");
    let issuer = simple_cn_name("Test CA");
    let spki = spki();

    let mut tbs_content = Vec::new();
    if let Some(v) = version {
        tbs_content.extend_from_slice(&tlv(0xA0, &tlv(0x02, &[v])));
    }
    tbs_content.extend_from_slice(&serial);
    tbs_content.extend_from_slice(&signature_algorithm());
    tbs_content.extend_from_slice(&issuer);
    tbs_content.extend_from_slice(&validity);
    tbs_content.extend_from_slice(&subject);
    tbs_content.extend_from_slice(&spki);
    tbs_content.extend_from_slice(tail);
    let tbs = seq(&tbs_content);

    seq(&concat(&[
        &tbs,
        &signature_algorithm(),
        &tlv(0x03, &[0x00]),
    ]))
}

fn signature_algorithm() -> Vec<u8> {
    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
}

fn spki() -> Vec<u8> {
    let alg = seq(&concat(&[
        &oid(&[1, 2, 840, 113549, 1, 1, 1]),
        &tlv(0x05, &[]),
    ]));
    seq(&concat(&[&alg, &tlv(0x03, &[0x00, 0x01, 0x00])]))
}

fn simple_cn_name(cn: &str) -> Vec<u8> {
    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn.as_bytes())]));
    let rdn = tlv(0x31, &atv);
    tlv(0x30, &rdn)
}

fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    out.extend_from_slice(len_bytes);
    out.extend_from_slice(content);
    out
}

fn oid(arcs: &[u64]) -> Vec<u8> {
    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
    for &arc in &arcs[2..] {
        content.extend_from_slice(&oid_arc(arc));
    }
    tlv(0x06, &content)
}

fn oid_arc(mut value: u64) -> Vec<u8> {
    let mut out = vec![(value % 128) as u8];
    value /= 128;
    while value > 0 {
        out.push(0x80 | (value % 128) as u8);
        value /= 128;
    }
    out.reverse();
    out
}

fn seq(content: &[u8]) -> Vec<u8> {
    tlv(0x30, content)
}

fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
    let mut out = vec![tag];
    out.extend_from_slice(&der_len(content.len()));
    out.extend_from_slice(content);
    out
}

fn der_len(n: usize) -> Vec<u8> {
    if n < 0x80 {
        vec![n as u8]
    } else {
        let mut body = Vec::new();
        let mut v = n;
        while v > 0 {
            body.push((v & 0xFF) as u8);
            v >>= 8;
        }
        body.reverse();
        let mut out = vec![0x80 | body.len() as u8];
        out.extend_from_slice(&body);
        out
    }
}

fn concat(parts: &[&[u8]]) -> Vec<u8> {
    let mut out = Vec::new();
    for part in parts {
        out.extend_from_slice(part);
    }
    out
}

